const WEIGHTS_BASE64 = "";
const BIASES_BASE64 = "SPtSu8uCI71feRY9TUYIvHk6Gb3H1Ju89iU6u4Uu7TykajI+H/DrvMOouLy8/0s8+VMNvOyOWztYq/g7OAoJvcyD+7yn2BI9gz3qulGrpzxbKjo9OVAzOyfO/rvB6CS8tX9Fu5nRCr0ABps85m6evPctCr37YsY88DgkvbRH2Lw=";

// Helper to base64 decode to Float32Array
function decodeFloat32(base64) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new Float32Array(bytes.buffer);
}

// Lazy load weights and biases
let cachedWeights = null;
let cachedBiases = null;

const bitmaps = {
  // Method to check if mask has a black pixel (0) at [x][y]
  isBlack: function(char, x, y) {
    const packedRows = BITMAPS_PACKED[char];
    if (!packedRows) return false;
    return (packedRows[x] & (1 << y)) !== 0;
  },
  get weights() {
    if (!cachedWeights) {
      cachedWeights = decodeFloat32(WEIGHTS_BASE64);
    }
    return cachedWeights;
  },
  get biases() {
    if (!cachedBiases) {
      cachedBiases = decodeFloat32(BIASES_BASE64);
    }
    return cachedBiases;
  }
};
